  <style>
    :root {
      --bg: #0d1117;
      --surface: #161b22;
      --surface2: #1c2128;
      --border: rgba(139,148,158,0.15);
      --text: #e6edf3;
      --text-dim: #8b949e;
      --text-muted: #484f58;

      /* Layer color system */
      --data-primary: #2d9cdb;
      --data-dim: rgba(45,156,219,0.15);
      --data-glow: rgba(45,156,219,0.3);

      --compute-primary: #27ae60;
      --compute-dim: rgba(39,174,96,0.15);
      --compute-glow: rgba(39,174,96,0.3);

      --serving-primary: #e67e22;
      --serving-dim: rgba(230,126,34,0.15);
      --serving-glow: rgba(230,126,34,0.3);

      --obs-primary: #e74c3c;
      --obs-dim: rgba(231,76,60,0.15);
      --obs-glow: rgba(231,76,60,0.3);

      --lineage-color: rgba(180,140,255,0.7);
      --feedback-color: rgba(255,210,80,0.8);
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      background: var(--bg);
      color: var(--text);
      font-family: 'IBM Plex Sans', 'Helvetica Neue', sans-serif;
      min-height: 100vh;
      padding: 32px;
    }

    .page-header {
      margin-bottom: 24px;
    }

    .page-title {
      font-size: 22px;
      font-weight: 600;
      letter-spacing: -0.3px;
      color: var(--text);
      margin-bottom: 4px;
    }

    .page-subtitle {
      font-size: 13px;
      color: var(--text-dim);
      font-family: 'IBM Plex Mono', monospace;
    }

    .diagram-container {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      overflow: hidden;
      position: relative;
    }

    svg {
      display: block;
      width: 100%;
    }

    /* Legend */
    .legend-panel {
      display: flex;
      gap: 32px;
      padding: 16px 24px;
      background: var(--surface2);
      border-top: 1px solid var(--border);
      flex-wrap: wrap;
      align-items: center;
    }

    .legend-group {
      display: flex;
      flex-direction: column;
      gap: 6px;
    }

    .legend-group-label {
      font-size: 10px;
      font-weight: 600;
      letter-spacing: 0.8px;
      text-transform: uppercase;
      color: var(--text-muted);
      font-family: 'IBM Plex Mono', monospace;
      margin-bottom: 2px;
    }

    .legend-items {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .legend-item {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 12px;
      color: var(--text-dim);
    }

    .legend-dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      flex-shrink: 0;
    }

    .legend-line {
      width: 24px;
      height: 2px;
      flex-shrink: 0;
    }

    .legend-line.dashed {
      background: repeating-linear-gradient(90deg, var(--lineage-color) 0px, var(--lineage-color) 4px, transparent 4px, transparent 8px);
    }

    .legend-line.feedback {
      background: repeating-linear-gradient(90deg, var(--feedback-color) 0px, var(--feedback-color) 4px, transparent 4px, transparent 8px);
    }

    .legend-line.solid {
      background: rgba(139,148,158,0.6);
    }
  </style>
</head>
